  // a layout the new time keeper sent before this device heard it took over (#61). It is
  // checked again against who is here now, and used only if it still passes
  const early = earlyLayouts.get(s.leader);
  earlyLayouts.clear();
  if (s.leader === id) sendLayout();
  else if (early && isValidJoins(early, [...Object.keys(s.peers), id])) { s.joins = early; emit('layout'); }

ch.on('presence', { event: 'sync' }, () => {
  const st = ch.presenceState();
  s.peers = {};
  for (const [key, metas] of Object.entries(st)) {
    const m = metas[metas.length - 1];
    if (!validPeerMeta(m)) continue;                        // a device that describes itself badly isn't counted
    s.peers[key] = { name: m.name, w: m.w, h: m.h, joinedAt: m.joinedAt };
  }
  // forget joins to devices that have left, so layouts never mention absent devices
  s.joins = s.joins.filter((j) => s.peers[j.a] && s.peers[j.b]);
  for (const k of earlyLayouts.keys()) if (!s.peers[k]) earlyLayouts.delete(k);   // nothing kept from devices that have left
  electLeader();
  if (s.leader === id) sendLayout();

test('a device that hears late that the time keeper left still ends up with the new time keeper’s layout', async () => {
  const devs = await room(), { A, B, C } = devs;
  leaves(devs, 'L');
  hear('A');                       // A hears first and takes over. B and C still count L
  await tick(100);
  assert.equal(A.leader, 'A'); assert.equal(B.leader, 'L');
  A.push('R', 400); B.push('L', 400);
  await tick(3000);
  assert.equal(A.joins.length, 1, 'A joined B');
  assert.deepEqual([B.joins, C.joins], [[], []], 'B and C, still counting L, did not use it yet');
  hear('C', 'B');                  // the two hear in the opposite order to the one they arrived in
  await settle();
  assert.deepEqual([B.leader, C.leader], ['A', 'A']);
  assert.deepEqual(B.joins, A.joins, 'B holds A’s layout');
  assert.deepEqual(C.joins, A.joins, 'C holds A’s layout');
